// The Release History changelog, newest release first. One entry per
// publish date; every change published that day goes in its `changes` list.
//
// Each change has:
//   type     new | improved | fixed | removed, or note for accessibility
//            checks, known-incomplete items and other notes that aren't a
//            change themselves (shown last, in their own group).
//   area     content (pages, patterns, media, copy) or site (features,
//            components, build, headers). Notes have no area.
//   summary  one plain sentence a reader can understand on its own, without
//            the type word (the badge says New, Fixed, and so on).
//   details  optional: the full description, shown when the summary is
//            opened. Leave it out when the summary already says everything.
//
// Changes can be listed in any order; the page groups them by type. Text in
// `backticks` renders as code. Historical entries keep the counts and wording
// true on their own date; don't update them to today's numbers.

export type ChangeType = 'new' | 'improved' | 'fixed' | 'removed' | 'note'
export type ChangeArea = 'content' | 'site'

export interface Change {
  type: ChangeType
  area?: ChangeArea
  summary: string
  details?: string
}

export interface Release {
  date: string
  changes: Change[]
}

